css:
.p20-page { display: grid; grid-template-rows: auto 1fr; min-height: 100cqh; overflow-x: clip; }
.p20-page > .deck { grid-row: 2; align-self: center; }
.p20-top { display: grid; gap: var(--s-2); width: 100%; max-width: 56rem; margin-inline: auto; padding: var(--s-3) var(--s-3) 0; grid-row: 1; }
.p20-top:empty { display: none; }
.p20-strip { --p20-sh: 9rem; }
.p20-strip--b { --p20-sh: 4.5rem; }
.p20-strip .deck { --card: max(var(--card-min), min(var(--card-max), calc(100cqw - 2rem), calc(100cqh - 2rem - var(--peek) - var(--s-3) - var(--controls-h) - var(--p20-sh)))); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p20-strip { --p20-sh: 17rem; } .p20-strip--b { --p20-sh: 6rem; } }
@media (max-width: 21.25rem) { .p20-strip { --p20-sh: 22rem; } .p20-strip--b { --p20-sh: 7rem; } }
.p20-win .deck-card__head { margin-top: 0; }
.p20-face { gap: var(--s-2); }
.p20-body { flex: 1 1 auto; min-height: 0; overflow: auto; display: grid; grid-auto-rows: min-content; gap: var(--s-3); align-content: start; padding-block: var(--s-1) var(--s-2); border-bottom: var(--w1) solid var(--rule); }
.p20-msg { flex: none; display: grid; gap: var(--s-2); }
.p20-msg:empty { display: none; }
.p20-foot { flex: none; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: var(--s-2); }
.dialog__foot.p20-foot2 { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); }
.p20-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -1); }
.p20-area { position: relative; }
.p20-count { position: absolute; right: var(--s-2); bottom: var(--s-1); font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); pointer-events: none; background: var(--white); padding-inline: var(--s-1); }
.p20-count.is-over { color: var(--ink); font-weight: var(--fw-bold); }
.textarea.p20-ta { min-height: 4rem; padding-bottom: 1.375rem; resize: none; }
.p20-pair { display: grid; grid-template-columns: repeat(auto-fit, minmax(9.5rem, 1fr)); gap: var(--s-3); align-items: start; }
.p20-pair .field { grid-template-columns: minmax(0, 1fr); }
.p20-pair .select { height: auto; min-width: 0; padding-block: var(--s-2); }
.p20-pair .select > span { min-width: 0; flex: 1 1 auto; overflow: hidden; overflow-wrap: anywhere; }
.p20-pair .select .motive { display: flex; max-width: 100%; }
.p20-pair + .menu { margin-top: calc(var(--s-2) * -1); }
.p20-full { grid-column: 1 / -1; }
.textarea.p20-name { min-height: var(--ctl-h); padding: var(--s-2) var(--s-3); resize: none; overflow-wrap: anywhere; }
.btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p20-tipw { position: relative; display: flex; min-width: 0; }
.p20-tipw > .btn { flex: 1 1 auto; width: 100%; }
.p20-tip { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }
.p20-win .hint { font-size: var(--fs-small); }
.p20-fade { opacity: 0.5; }
.p20-pressed { border-width: var(--w2); border-color: var(--ink); text-decoration: underline; text-underline-offset: 0.25em; }

.dialog.p20-dlg { max-height: 100%; }
.dialog__foot.p20-foot3 { flex-direction: column; }
.dialog__foot.p20-foot3 > * { flex: none; }
.p20-dlg .dialog__body p + p { color: var(--muted); }
.p20-dlg .banner { padding-inline: var(--s-3); }
.p20-dlg .dialog__foot .p20-tipw { position: relative; }
.p20-dtip { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }

.p-menuwrap { position: relative; display: flex; }
.ibtn.is-open { border: var(--w2) solid var(--ink); }
.p20-menu { position: absolute; z-index: 30; right: 0; top: calc(100% + var(--s-1)); min-width: 12rem; max-width: calc(100cqw - var(--s-5)); }
.p20-menu .menu__item { min-height: var(--row-h); }


.deck-card__foot.p-solo > :first-child { justify-self: center; }
.p20-text { overflow: auto; }
.p20-solo { position: absolute; top: var(--s-2); right: var(--s-2); z-index: 5; }
.p20-both .deck-card__title { padding-top: 0; padding-right: var(--s-6); margin-bottom: var(--s-2); }
.p20-text.is-empty { color: var(--muted); }
.p20-menu .menu__item { justify-content: flex-start; }
.p20-ring { outline: var(--focus-ring); outline-offset: var(--focus-offset); }
.p20-dlg .dialog__body p + p { font-size: var(--fs-cap); line-height: var(--lh-cap); }
.p20-wordbox .field { margin-top: var(--s-1); }
.p20-tipk { position: absolute; z-index: 30; top: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: 14rem; }

@media (max-width: 21.25rem) {
  .composer { gap: var(--s-1); padding-inline: var(--s-1); }
  .composer .input { padding-inline: var(--s-1); }
  .composer .input::placeholder { font-size: var(--fs-small); }
}

.p20-dlg .dialog__foot:has(.p20-tipw) { display: grid; grid-template-columns: 1fr 1fr; }
.p20-dlg .dialog__foot .p20-tipw { display: contents; }
.p20-dlg .dialog__foot .p20-tipw > .tip { position: static; translate: none; width: auto; max-width: none; grid-column: 1 / -1; grid-row: 2; text-align: start; }

@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .p20-dlg .dialog__head { flex-wrap: wrap; }
  .p20-dlg .dialog__head > .ibtn { order: -1; margin-inline-start: auto; }
  .p20-dlg .dialog__title { flex: 1 1 100%; }
}
@media (max-width: 21.25rem) { .scrim { padding: var(--s-3); } }

.deck-card__head:has(.p20-tipk) { flex-wrap: wrap; }
.p-menuwrap:has(> .p20-tipk) { display: contents; }
.p20-tipk { position: static; order: 3; flex: 0 0 100%; width: auto; max-width: none; text-align: end; }

.mcard .deck-card__back-foot { background: transparent; }
.mcard .hint { color: var(--ink); }
.mcard .p20-text.is-empty { color: var(--ink); }
